import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Button from '../components/ui/Button';
import '../styles/pages/MapViewPage.css';

// Tipos de césped representados por colores
const grassTypes = [
  { id: 'grass1', color: '#8eb22c' }, // Verde claro
  { id: 'grass2', color: '#669922' }, // Verde medio
  { id: 'grass3', color: '#548c18' }, // Verde más oscuro
  { id: 'grass4', color: '#7cac26' }  // Verde amarillento
];

interface Tile {
  id: string;
  type: string;
  grassTypeId: string;
}

const MapViewPage: React.FC = () => {
  const navigate = useNavigate();
  const [map, setMap] = useState<Tile[][]>([]);
  const [loading, setLoading] = useState(true);
  
  // Configuración del mapa
  const mapWidth = 20;
  const mapHeight = 15;
  
  useEffect(() => {
    // Generar mapa aleatorio con los diferentes tipos de césped
    generateRandomMap();
  }, []);
  
  const generateRandomMap = () => {
    setLoading(true);
    
    const newMap: Tile[][] = [];
    
    for (let y = 0; y < mapHeight; y++) {
      const row: Tile[] = [];
      for (let x = 0; x < mapWidth; x++) {
        // Seleccionar aleatoriamente un tipo de césped
        const randomIndex = Math.floor(Math.random() * grassTypes.length);
        const grassType = grassTypes[randomIndex];
        
        row.push({
          id: `tile-${x}-${y}`,
          type: 'grass',
          grassTypeId: grassType.id
        });
      }
      newMap.push(row);
    }
    
    setMap(newMap);
    setLoading(false);
  };
  
  const handleRefreshMap = () => {
    generateRandomMap();
  };
  
  const handleBackToMenu = () => {
    navigate('/menu');
  };
  
  // Obtener el color correspondiente al tipo de césped
  const getGrassColor = (grassTypeId: string): string => {
    const grassType = grassTypes.find(type => type.id === grassTypeId);
    return grassType ? grassType.color : '#8eb22c'; // Color por defecto
  };
  
  if (loading) {
    return <div className="loading-screen">Generando mapa...</div>;
  }
  
  return (
    <div className="map-view-page">
      <div className="map-view-header">
        <h1>Visor de Mapa</h1>
        <div className="map-controls">
          <Button onClick={handleRefreshMap}>Generar Nuevo Mapa</Button>
          <Button onClick={handleBackToMenu}>Volver al Menú</Button>
        </div>
      </div>
      
      <div className="map-container">
        <div 
          className="game-map-grid" 
          style={{ 
            gridTemplateColumns: `repeat(${mapWidth}, 48px)`,
            gridTemplateRows: `repeat(${mapHeight}, 48px)`
          }}
        >
          {map.flat().map((tile) => (
            <div 
              key={tile.id} 
              className="map-tile"
              style={{ backgroundColor: getGrassColor(tile.grassTypeId) }}
            >
              {/* Podemos añadir elementos decorativos si es necesario */}
              <div className="tile-overlay"></div>
            </div>
          ))}
        </div>
      </div>
      
      <div className="map-info">
        <h3>Leyenda</h3>
        <div className="map-legend">
          {grassTypes.map(type => (
            <div key={type.id} className="legend-item">
              <div 
                className="legend-color"
                style={{ backgroundColor: type.color }}
              ></div>
              <span>Césped tipo {type.id.replace('grass', '')}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default MapViewPage;
